function removeCheckerboard(image){const surface=document.createElement('canvas');surface.width=image.naturalWidth;surface.height=image.naturalHeight;const paint=surface.getContext('2d',{willReadFrequently:true});paint.drawImage(image,0,0);const pixels=paint.getImageData(0,0,surface.width,surface.height),data=pixels.data,width=surface.width,height=surface.height,seen=new Uint8Array(width*height),queue=[];const background=index=>{const offset=index*4,r=data[offset],g=data[offset+1],b=data[offset+2],spread=Math.max(r,g,b)-Math.min(r,g,b),light=(r+g+b)/3;return data[offset+3]<8||(spread<14&&light>132);};for(let x=0;x<width;x++){queue.push(x,(height-1)*width+x);}for(let y=1;y<height-1;y++){queue.push(y*width,y*width+width-1);}for(let cursor=0;cursor<queue.length;cursor++){const index=queue[cursor];if(index<0||index>=width*height||seen[index]||!background(index))continue;seen[index]=1;data[index*4+3]=0;const x=index%width;if(x>0)queue.push(index-1);if(x<width-1)queue.push(index+1);if(index>=width)queue.push(index-width);if(index<width*(height-1))queue.push(index+width);}paint.putImageData(pixels,0,0);return surface;}
function removeDarkBackdrop(image){const surface=document.createElement('canvas');surface.width=384;surface.height=256;const paint=surface.getContext('2d',{willReadFrequently:true});paint.drawImage(image,0,0,surface.width,surface.height);const pixels=paint.getImageData(0,0,surface.width,surface.height),data=pixels.data,width=surface.width,height=surface.height,seen=new Uint8Array(width*height),queue=[];const background=index=>{const offset=index*4,r=data[offset],g=data[offset+1],b=data[offset+2],light=(r+g+b)/3,warm=r-b;return data[offset+3]<8||light<34||(r<132&&g<96&&b<68&&warm<82);};for(let x=0;x<width;x++)queue.push(x,(height-1)*width+x);for(let y=1;y<height-1;y++)queue.push(y*width,y*width+width-1);for(let cursor=0;cursor<queue.length;cursor++){const index=queue[cursor];if(index<0||index>=width*height||seen[index]||!background(index))continue;seen[index]=1;data[index*4+3]=0;const x=index%width;if(x>0)queue.push(index-1);if(x<width-1)queue.push(index+1);if(index>=width)queue.push(index-width);if(index<width*(height-1))queue.push(index+width);}paint.putImageData(pixels,0,0);return surface;}
