function normalizeRunSnapshot(value){if(!value||typeof value!=='object')return null;const nextFloor=Math.floor(Number(value.floor)),nextWave=Math.floor(Number(value.wave)),nextMap=value.map,nextPlayer=value.p;if(nextFloor<1||nextFloor>6||nextWave<1||!Array.isArray(nextMap)||nextMap.length!==ROWS||nextMap.some(row=>!Array.isArray(row)||row.length!==COLS)||!nextPlayer||typeof nextPlayer!=='object'||!Number.isFinite(Number(nextPlayer.hp))||Number(nextPlayer.hp)<=0||!Number.isFinite(Number(nextPlayer.maxHp)))return null;const copy=safeRunClone(value);copy.floor=nextFloor;copy.wave=nextWave;copy.difficulty=difficulties[copy.difficulty]?copy.difficulty:'easy';copy.chosen=weaponInfo[copy.chosen]?copy.chosen:'sword';copy.roomKind=rooms[copy.roomKind]?copy.roomKind:'ruins';for(const key of ['enemies','shots','drops','hazards','path','logs','stock'])if(!Array.isArray(copy[key]))copy[key]=[];return copy;}
