function clearRunSnapshot(){try{localStorage.removeItem(RUN_KEY);return true;}catch(error){markStorageFailure(error);return false;}}
function saveRunSnapshot(reason='远征存档'){if(!running||finished||!p||p.hp<=0)return false;try{const serialized=JSON.stringify(makeRunSnapshot());localStorage.setItem(RUN_KEY,serialized);if(localStorage.getItem(RUN_KEY)!==serialized)throw new Error('远征存档写入后无法读取');storageState.available=true;storageState.error='';storageState.lastSavedAt=Date.now();updateSaveStatus();return true;}catch(error){markStorageFailure(error);toast(`⚠ ${reason}失败：请导出存档备份`);return false;}}
function restoreRunSnapshot(snapshot){const saved=normalizeRunSnapshot(snapshot);if(!saved)return false;difficulty=saved.difficulty;chosen=saved.chosen;floor=saved.floor;wave=saved.wave;roomKind=saved.roomKind;map=saved.map;const fresh=makePlayer(chosen);p={...fresh,...saved.p,cd:{...fresh.cd,...saved.p.cd},buffs:{...fresh.buffs,...saved.p.buffs},elixirs:{...fresh.elixirs,...saved.p.elixirs},equipment:{...fresh.equipment,...saved.p.equipment}};p.weapons=Array.isArray(saved.p.weapons)&&saved.p.weapons.length?saved.p.weapons:fresh.weapons;p.weaponIndex=clamp(Math.floor(Number(p.weaponIndex)||0),0,p.weapons.length-1);const activeWeaponId=saved.p.equipment?.weapon?.id;p.equipment.weapon=p.weapons.find(item=>item?.id===activeWeaponId)||p.weapons[p.weaponIndex]||fresh.equipment.weapon;p.weaponIndex=Math.max(0,p.weapons.indexOf(p.equipment.weapon));p.inventory=Array.isArray(saved.p.inventory)?saved.p.inventory:[];p.artifacts=Array.isArray(saved.p.artifacts)?saved.p.artifacts:[];p.attackTimeline=null;p.attackAnim=0;p.hit=0;p.knockdown=0;p.deathAnim=0;p.executionAnim=0;enemies=saved.enemies.map(enemy=>({...enemy,attackTimeline:null,attackAnim:0,hit:0,knockdown:0}));shots=saved.shots;drops=saved.drops;hazards=saved.hazards;path=saved.path;target=saved.targetId==null?null:enemies.find(enemy=>enemy.id===saved.targetId)||null;cleared=Boolean(saved.cleared);elapsed=Math.max(0,Number(saved.elapsed)||0);logs=saved.logs.slice(0,5);stock=saved.stock;refreshCount=Math.max(0,Math.floor(Number(saved.refreshCount)||0));pendingTalents=Math.max(0,Math.floor(Number(saved.pendingTalents)||0));shopVisits=Math.max(0,Math.floor(Number(saved.shopVisits)||0));eliteNext=Boolean(saved.eliteNext);eliteRound=Boolean(saved.eliteRound);committedRunKills=Math.max(0,Math.floor(Number(saved.committedRunKills)||0));cinematic=saved.cinematic||null;lastBossDefeat=saved.lastBossDefeat||null;effects=[];corpses=[];pendingCast=null;queuedCast=null;deathSequence=0;hitStop=0;slowMotion=0;cameraZoom=0;screenShake=0;screenFlash=0;runRewarded=false;finished=false;running=true;enemyId=Math.max(enemyId,...enemies.map(enemy=>Number(enemy.id)||0));lootId=Math.max(lootId,...drops.map(drop=>Number(drop.id)||0));closeModal();log(`已读取远征存档：第 ${floor} 层第 ${wave} 场。`);updateUI();return true;}
function resumeRun(){const saved=readRunSnapshot();if(saved&&restoreRunSnapshot(saved)){toast('远征现场已完整恢复。');return true;}clearRunSnapshot();startScreen();toast('没有可继续的完整远征存档。');return false;}
function saveAndExit(){commitRunProgress('保存并退出');if(!saveRunSnapshot('保存并退出'))return false;running=false;paused=true;currentModal='';startScreen();toast('远征已完整保存，可从主界面继续。');return true;}
function settleAndExit(){if(!running||finished)return false;clearRunSnapshot();endRun(false);return true;}
function saveManagerMarkup(){return `<div class="save-tools"><button data-action="export-save">导出存档</button><button data-action="import-save">导入存档</button></div><p class="save-status ${storageState.available?'':'save-error'}">${saveStatusText()}</p>`;}
function throneMarkup(){if(profile.finalThrone)return '<div class="throne-panel throne-complete"><strong>♛ 最后的王座</strong><span>永久生效 · 后续对局全属性 +25%</span></div>';if(profile.throneFragments>0){const invested=Math.min(4,profile.throneFragments),chance=invested*25;return `<div class="throne-panel"><div><strong>♜ 王座碎片 ×${profile.throneFragments}</strong><span>${invested>=4?'四片共鸣 · 必定成功':`幸运重铸成功率 ${chance}%`} · 每枚提供 25%</span></div><button data-action="synthesize-throne">合成王座</button></div>`;}return '<div class="throne-panel throne-locked"><strong>◇ 最后的王座</strong><span>集齐 4 枚必定重铸；不足时每枚提供 25% 幸运成功率</span></div>';}
function confirmThroneSynthesis(){if(profile.finalThrone||profile.throneFragments<1)return;const invested=Math.min(4,profile.throneFragments),chance=invested*25;openModal('throne-confirm',`<div class="modal-eyebrow">THE FINAL THRONE</div><h2 class="modal-title">重铸最后的王座？</h2><p class="modal-subtitle">本次投入并消耗 ${invested} 枚王座碎片，成功率为 <strong class="gold">${chance}%</strong>。${chance<100?'<br>若幸运重铸失败，投入的碎片也会破碎。':'<br>四枚碎片已经完整共鸣，本次必定成功。'}<br>成功后，今后每次远征都会获得全属性 +25%。</p><div class="modal-actions"><button data-action="main-menu">暂不合成</button><button class="primary" data-action="confirm-throne">${chance<100?'尝试幸运重铸':'完整重铸王座'}</button></div>`);}
function synthesizeThrone(rng=Math.random){if(profile.finalThrone||profile.throneFragments<1)return false;const invested=Math.min(4,profile.throneFragments),chance=invested*.25;profile.throneFragments-=invested;const success=rng()<chance;if(success)profile.finalThrone=true;saveProfile('王座合成');tone(success?180:85,success?.7:.38,'sawtooth',.05);startScreen();toast(success?'最后的王座已经重铸：后续对局全属性 +25%！':`幸运重铸失败，${invested} 枚碎片化为灰烬。`);return success;}
function exportSave(){commitRunProgress('导出前');if(running&&!finished)saveRunSnapshot('导出前');const payload={kind:'abyss-scavenger-save',version:2,exportedAt:new Date().toISOString(),profile:normalizeProfile(profile),best,difficulty,run:running&&!finished?makeRunSnapshot():readRunSnapshot()};try{const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`abyss-scavenger-save-${new Date().toISOString().slice(0,10)}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0);toast('永久进度与远征现场已导出。');}catch(error){toast(`导出失败：${error?.message||'浏览器不支持下载'}`);}}
function chooseImportFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;input.addEventListener('change',async()=>{const file=input.files?.[0];input.remove();if(!file)return;try{if(file.size>1024*1024)throw new Error('存档文件超过 1MB');const data=JSON.parse(await file.text());if(data?.kind!=='abyss-scavenger-save'||!data.profile)throw new Error('这不是《深渊拾荒者》存档');const importedRun=data.run==null?null:normalizeRunSnapshot(data.run);if(data.run!=null&&!importedRun)throw new Error('远征现场数据已损坏');pendingImport={profile:normalizeProfile(data.profile),best:data.best&&typeof data.best==='object'?data.best:null,difficulty:difficulties[data.difficulty]?data.difficulty:'easy',run:importedRun};openModal('confirm-import',`<div class="modal-eyebrow">RESTORE THE DESCENT</div><h2 class="modal-title">确认导入存档？</h2><p class="modal-subtitle">即将载入 ◆ ${pendingImport.profile.diamonds} 钻石、${pendingImport.profile.totalKills} 次击杀、${Object.keys(pendingImport.profile.purchases).length} 件永久升级。${pendingImport.run?`<br>包含第 ${pendingImport.run.floor} 层第 ${pendingImport.run.wave} 场的完整远征现场。`:''}<br>当前本地进度将被这份备份替换。</p><div class="modal-actions"><button data-action="main-menu">取消</button><button class="primary" data-action="confirm-import">确认导入</button></div>`);}catch(error){toast(`导入失败：${error?.message||'文件损坏'}`);startScreen();}});document.body.append(input);input.click();}
function applyImportedSave(){if(!pendingImport)return;profile=normalizeProfile(pendingImport.profile);best=pendingImport.best;difficulty=pendingImport.difficulty;if(pendingImport.run)try{localStorage.setItem(RUN_KEY,JSON.stringify(pendingImport.run));}catch(error){markStorageFailure(error);}else clearRunSnapshot();pendingImport=null;saveProfile('导入存档');saveBest();if(best&&Number.isFinite(best.kills))$('best').textContent=`本机纪录：${best.won?'已通关':`第 ${best.floor} 层`} · ${best.kills} 击杀`;startScreen();toast('存档导入成功。');}
function honorList(){return [{name:'初次下潜',desc:'完成第一场战斗',earned:profile.totalKills>0},{name:'穿越半途',desc:'抵达第三层',earned:profile.bestFloor>=3},{name:'王权见证者',desc:'抵达第六层',earned:profile.bestFloor>=6},{name:'深渊征服者',desc:'通关任意难度',earned:profile.totalWins>0},{name:'不屈拾荒者',desc:'累计击败 250 名敌人',earned:profile.totalKills>=250},{name:'无光凯旋',desc:'通关困难难度',earned:profile.hardWins>0}];}
function initialStatsPreviewMarkup(){const preview=makePlayer(chosen);applyMetaUpgrades(preview);const stats=playerStats(preview),speed=Math.round(155*stats.weapon.speed*(1+(preview.bonusSpeed||0))*(preview.globalStatMultiplier||1));return `<div class="initial-preview"><div><span>初始生命</span><strong>${preview.maxHp}</strong></div><div><span>攻击</span><strong>${stats.attack}</strong></div><div><span>护甲</span><strong>${stats.armor}</strong></div><div><span>暴击</span><strong>${stats.crit.toFixed(stats.crit%1?1:0)}%</strong></div><div><span>速度</span><strong>${speed}</strong></div><div><span>吸血</span><strong>${(stats.leech*leechDifficultyMultiplier()).toFixed(1)}%</strong></div></div>`;}
function updateOpeningCopy(scene){const story=OPENING_STORY[scene];if(!story)return;$('opening-kicker').textContent=story.kicker;$('opening-title').textContent=story.title;$('opening-story').textContent=story.text;$('opening-chapter').textContent=`序章 · ${String(scene+1).padStart(2,'0')} / ${String(OPENING_STORY.length).padStart(2,'0')}`;const copy=$('opening-title').parentElement;if(copy){copy.classList.remove('cg-copy-enter');void copy.offsetWidth;copy.classList.add('cg-copy-enter');}}
function startOpeningCG(){if(modal.open)modal.close();currentModal='opening';paused=true;running=false;openingScene=-1;openingCinematic={time:0,duration:21};document.body?.classList?.add('opening-active');const overlay=$('opening-cg');overlay.hidden=false;overlay.classList.remove('cg-ending');updateOpeningCG(0);}
function finishOpeningCG(){if(!openingCinematic)return;openingCinematic=null;openingScene=-1;document.body?.classList?.remove('opening-active');$('opening-cg').hidden=true;currentModal='';startScreen();}
function updateOpeningCG(dt){if(!openingCinematic)return;openingCinematic.time+=Math.max(0,dt);if(openingCinematic.time>=openingCinematic.duration){finishOpeningCG();return;}const segment=openingCinematic.duration/OPENING_STORY.length,scene=Math.min(OPENING_STORY.length-1,Math.floor(openingCinematic.time/segment));if(scene!==openingScene){openingScene=scene;updateOpeningCopy(scene);}$('opening-progress').style.width=`${openingCinematic.time/openingCinematic.duration*100}%`;}
function drawOpeningCG(){if(!openingCinematic)return;const surface=$('opening-canvas'),paint=surface?.getContext?.('2d');if(!paint)return;const segment=openingCinematic.duration/OPENING_STORY.length,local=openingCinematic.time%segment/segment;drawOpeningStoryFrame(paint,openingCinematic.time,openingScene<0?0:openingScene,local);}
function startScreen(){if(currentModal==='loadout'){loadoutScreen();return;}const earned=honorList().filter(h=>h.earned).length,savedRun=readRunSnapshot(),resumeCard=savedRun?`<button class="main-menu-card main-menu-primary" data-action="resume-run"><span class="menu-rune">↻</span><span><strong>继续远征</strong><small>第 ${savedRun.floor} 层 · 第 ${savedRun.wave} 场 · ${formatTime(savedRun.elapsed||0)}</small></span><b>→</b></button>`:'';openModal('start',`<div class="start-layout main-menu-layout"><div class="hero-showcase"><img src="./hero-gothic.png" alt="披甲的哥特拾荒者"><span>BLACK GOLD ALCHEMY</span></div><div class="start-copy"><div class="modal-eyebrow">THE DESCENT AWAITS</div><h2 class="modal-title">深渊拾荒者</h2><div class="menu-ledger"><span>◆ ${profile.diamonds} 钻石</span><span>${difficulties[difficulty].name}难度</span><span>${earned} / ${honorList().length} 荣誉</span><span>符文 ${profile.equippedRuneIds.length} / 6</span></div>${initialStatsPreviewMarkup()}<div class="main-menu-stack">${resumeCard}<button class="main-menu-card ${savedRun?'':'main-menu-primary'}" data-action="new-run"><span class="menu-rune">†</span><span><strong>开始游戏</strong><small>${savedRun?'选择兵器并开始新远征':'选择兵器，进入完整六层远征'}</small></span><b>→</b></button><button class="main-menu-card" data-action="difficulty"><span class="menu-rune">◆</span><span><strong>选择难度</strong><small>当前：${difficulties[difficulty].name} · 每层 ${normalWaveCount()} 场普通战斗</small></span><b>→</b></button><button class="main-menu-card" data-action="runes"><span class="menu-rune">◈</span><span><strong>符文圣坛</strong><small>装配晶元，永久强化每次远征的初始属性</small></span><b>→</b></button><button class="main-menu-card" data-action="honors"><span class="menu-rune">♜</span><span><strong>查看荣誉</strong><small>查看远征纪录与已解锁荣誉</small></span><b>→</b></button><button class="main-menu-card" data-action="meta-shop"><span class="menu-rune">✦</span><span><strong>商城</strong><small>使用钻石购买永久开局补给</small></span><b>→</b></button></div>${throneMarkup()}${saveManagerMarkup()}<p class="modal-note">战斗结束自动保存永久进度 · 暂停菜单可保存完整远征现场或按当前进度结算<br>导出备份会同时包含永久进度与未完成远征 · 主界面商城和局内商店相互独立</p></div></div>`);}
function loadoutScreen(){openModal('loadout',`<div class="start-layout"><div class="hero-showcase"><img src="./hero-gothic.png" alt="披甲的哥特拾荒者"><span>${difficulties[difficulty].name.toUpperCase()} DESCENT</span></div><div class="start-copy"><div class="modal-eyebrow">CHOOSE YOUR PATH · ${difficulties[difficulty].name}难度</div><h2 class="modal-title">选择起始兵器</h2><div class="story-window" aria-label="深渊序章"><div class="story-track"><p>灰潮吞没最后一座边境城后，<br>一束不属于人间的烛火在废墟下亮起。</p><p>六层被遗忘的王国沉睡于地底，<br>每一道门后，都有守墓者等待新的躯壳。</p><p>你带着一把旧兵器和无人认领的名字下行，<br>寻找黄金，也寻找深渊不愿归还的真相。</p><p class="story-last">烛火将熄。拾荒者，选择你的兵器。</p></div></div><div class="weapon-grid">${Object.entries(weaponInfo).map(([key,w])=>`<button class="weapon-choice ${key===chosen?'selected':''}" data-weapon="${key}"><span class="weapon-symbol">${w.symbol}</span><strong>${w.name}</strong><small>${key==='sword'?'近战横扫 · 攻速快<br>贴身战斗，打击多个目标':key==='bow'?'远程射击 · 灵活<br>保持距离，逐个击破':'奥术弹 · 范围爆炸<br>火力更强，攻击较慢'}</small></button>`).join('')}</div><button class="primary wide" data-action="start">踏入深渊 →</button><button class="wide" data-action="main-menu">返回主界面</button></div></div><p class="modal-note">WASD / 鼠标点击移动 · 点击敌人 / 空格攻击 · Shift / 1 / 2 技能<br>${difficulties[difficulty].name}难度每层 ${normalWaveCount()} 场普通战斗，再迎战首领。</p>`);}
function difficultyScreen(){openModal('difficulty',`<div class="modal-eyebrow">CHOOSE THE DESCENT</div><h2 class="modal-title">选择难度</h2><p class="modal-subtitle">越高难度拥有更长的战线、更凶猛的敌人与更高钻石结算。完成全部普通战斗后才会出现首领。</p><div class="weapon-grid difficulty-grid">${Object.entries(difficulties).map(([id,d])=>`<button class="weapon-choice ${difficulty===id?'selected':''}" data-difficulty="${id}"><span class="weapon-symbol">${id==='easy'?'◇':id==='normal'?'◆':id==='hard'?'✦':id==='hell'?'♨':'♛'}</span><strong>${d.name}</strong><small>${d.desc}<br>每层 ${normalWaveCount(id)} 场普通战斗 + 1 场首领战</small></button>`).join('')}</div><div class="modal-actions"><button class="primary" data-action="main-menu">确认并返回</button></div>`);}
function runeScreen(){const equipped=new Set(profile.equippedRuneIds),slots=Array.from({length:6},(_,i)=>{const chip=profile.runeChips.find(item=>item.id===profile.equippedRuneIds[i]);return chip?`<button class="rune-slot filled" style="--rune:${runeGrades[chip.grade].color}" data-rune-unequip="${chip.id}"><b>${chip.grade==='blue'||chip.grade==='gold'?'✦':runeStats[chip.stat]?.symbol||'◈'}</b><span>${runeGrades[chip.grade].name}</span><small>点击卸下</small></button>`:`<div class="rune-slot"><b>◇</b><span>空槽</span><small>最多装配六枚</small></div>`;}).join(''),cards=profile.runeChips.map(chip=>{const grade=runeGrades[chip.grade],trait=chip.grade==='blue'?(blueRuneTraits.find(t=>t.id===chip.trait)||blueRuneTraits[0]):chip.grade==='gold'?(goldRuneTraits.find(t=>t.id===chip.trait)||goldRuneTraits[0]):null;return `<div class="item-card rune-card ${chip.grade}-rune" style="--item:${grade.color}"><strong>${chip.grade==='blue'||chip.grade==='gold'?'✦':runeStats[chip.stat]?.symbol||'◈'} ${grade.name}${trait?` · ${trait.name}`:` · ${runeStats[chip.stat]?.name||'生命'}`}</strong><p>${runeDescription(chip)}</p><button data-rune-${equipped.has(chip.id)?'unequip':'equip'}="${chip.id}" ${!equipped.has(chip.id)&&equipped.size>=6?'disabled':''}>${equipped.has(chip.id)?'卸下':'装配'}</button></div>`;}).join('');openModal('runes',`<div class="modal-eyebrow">RUNIC SANCTUM · ${profile.runeChips.length} 枚晶元</div><h2 class="modal-title">符文圣坛</h2><p class="modal-subtitle rune-lore">群星坠入深渊时，碎光在死者的甲胄中凝成了晶元。<br>将它们嵌入古老石环，下一次踏过雾门的人，便会带着前世未熄的力量。</p><details class="rune-codex"><summary><span>◈</span><strong>晶元秘录</strong><small>点击查阅隐藏规则</small></summary><p>符文保存在本机的当前浏览器中，并永久影响每次远征的初始属性。六位首领各必定掉落 1 枚，普通关卡另有 0.35% 概率发现晶元。品质概率为：白晶 85%、翠绿 12%、湛蓝 2.9%、鎏金 0.1%。蓝、金符文会全面提升属性并附带独特机制。</p></details><div class="rune-slots">${slots}</div><div class="inventory-grid rune-inventory">${cards||'<p class="empty">石环仍在沉睡。深入遗迹，让第一枚晶元记住你的名字。</p>'}</div><div class="modal-actions"><button class="primary" data-action="main-menu">返回主界面</button></div>`);}
function equipRune(id){if(profile.equippedRuneIds.includes(id)||profile.equippedRuneIds.length>=6||!profile.runeChips.some(chip=>chip.id===id))return;profile.equippedRuneIds.push(id);saveProfile('符文装配保存');runeScreen();}
function unequipRune(id){profile.equippedRuneIds=profile.equippedRuneIds.filter(item=>item!==id);saveProfile('符文装配保存');runeScreen();}
function honorsScreen(){const honors=honorList();openModal('honors',`<div class="modal-eyebrow">HALL OF HONOR</div><h2 class="modal-title">拾荒者荣誉</h2><p class="modal-subtitle">累计远征 ${profile.totalRuns} 次 · 通关 ${profile.totalWins} 次 · 击败 ${profile.totalKills} 名敌人</p><div class="inventory-grid">${honors.map(h=>`<div class="item-card ${h.earned?'golden-item':''}"><strong>${h.earned?'◆':'◇'} ${h.name}</strong><p>${h.desc}<br>${h.earned?'已经获得':'尚未获得'}</p></div>`).join('')}</div><div class="modal-actions"><button class="primary" data-action="main-menu">返回主界面</button></div>`);}
function metaShopScreen(category=metaCategory){metaCategory=category;const categories={all:'全部',supply:'补给',body:'体魄',combat:'武技',arcane:'奥术',fortune:'财富'},items=category==='all'?metaGoods:metaGoods.filter(item=>item.category===category),ownedCount=metaGoods.filter(item=>profile.purchases[item.id]).length;openModal('meta-shop',`<div class="modal-eyebrow">BETWEEN DESCENTS · ${ownedCount} / ${metaGoods.length}</div><h2 class="modal-title">深渊商城 <span class="gold" style="font-size:21px">◆ ${profile.diamonds}</span></h2><p class="modal-subtitle">36 件永久升级分属五条成长路线。这里使用钻石，和局内金币商店完全独立。</p><div class="meta-filters">${Object.entries(categories).map(([id,name])=>`<button data-meta-category="${id}" ${category===id?'class="primary"':''}>${name}</button>`).join('')}</div><div class="inventory-grid meta-inventory">${items.map(item=>{const owned=profile.purchases[item.id];return `<div class="item-card ${owned?'golden-item':''}"><strong>✦ ${item.name}</strong><p>${item.desc}<br>${owned?'永久生效':categories[item.category]}</p><button data-meta="${item.id}" ${owned||profile.diamonds<item.cost?'disabled':''}>${owned?'已拥有':`购买 · ◆ ${item.cost}`}</button></div>`;}).join('')}</div><div class="modal-actions"><button class="primary" data-action="main-menu">返回主界面</button></div>`);}
function selectDifficulty(id){if(difficulties[id]){difficulty=id;saveProfile('难度设置保存');}return difficulty;}
function buyMeta(id){const item=metaGoods.find(g=>g.id===id);if(!item||profile.purchases[id]||profile.diamonds<item.cost)return;profile.diamonds-=item.cost;profile.purchases[id]=true;saveProfile();tone(680,.18);metaShopScreen(metaCategory);}
function applyRuneBonuses(player){for(const id of profile.equippedRuneIds){const chip=profile.runeChips.find(item=>item.id===id);if(!chip)continue;if(chip.grade==='white'||chip.grade==='green'){const strong=chip.grade==='green',values={hp:strong?200:80,attack:strong?5:2,armor:strong?5:2,speed:strong?.05:.02,leech:strong?5:2};if(chip.stat==='hp'){player.maxHp+=values.hp;player.hp+=values.hp;}if(chip.stat==='attack')player.bonusAttack+=values.attack;if(chip.stat==='armor')player.bonusArmor+=values.armor;if(chip.stat==='speed')player.bonusSpeed+=values.speed;if(chip.stat==='leech')player.bonusLeech+=values.leech;continue;}const gold=chip.grade==='gold';player.maxHp+=gold?360:120;player.hp+=gold?360:120;player.bonusAttack+=gold?12:4;player.bonusArmor+=gold?8:3;player.bonusCrit+=gold?6:2;player.bonusSpeed+=gold?.08:.03;player.bonusLeech+=gold?8:2;player.maxMana+=gold?40:15;player.mana+=gold?40:15;if(chip.grade==='blue'){if(chip.trait==='starwell'){player.maxMana+=20;player.mana+=20;player.manaRegen+=.25;}if(chip.trait==='bloodmoon')player.bonusLeech+=4;if(chip.trait==='swift'){player.bonusSpeed+=.04;player.bonusCrit+=3;}}else{if(chip.trait==='sovereign'){player.bonusAttack+=8;player.bonusArmor+=6;}if(chip.trait==='infinite'){player.runeManaCost=.8;player.runeCooldown=.9;}if(chip.trait==='hunter'){player.runeBossDamage=.18;player.bonusCrit+=6;}}}}
function applyMetaUpgrades(player){for(const item of metaGoods)if(profile.purchases[item.id])item.apply(player);applyRuneBonuses(player);if(profile.finalThrone){player.globalStatMultiplier=1.25;player.maxHp=Math.round(player.maxHp*1.25);player.hp=player.maxHp;player.maxMana=Math.round(player.maxMana*1.25);player.mana=player.maxMana;player.manaRegen*=1.25;}}
function start(){clearRunSnapshot();p=makePlayer(chosen);applyMetaUpgrades(p);p.artifacts=[];floor=1;wave=0;roomKind='ruins';map=createMap(1,roomKind);enemies=[];shots=[];effects=[];drops=[];hazards=[];path=[];target=null;pendingCast=null;queuedCast=null;elapsed=0;logs=[];pendingTalents=0;shopVisits=0;eliteNext=false;finished=false;runRewarded=false;committedRunKills=0;cinematic=null;lastBossDefeat=null;deathSequence=0;corpses=[];hitStop=0;slowMotion=0;cameraZoom=0;running=true;closeModal();if(localQaSafe)p.invuln=99999;log(`以${difficulties[difficulty].name}难度踏入苔影遗迹。愿火光照见归途。`);if(profile.equippedRuneIds.length)log(`符文圣坛回应：${profile.equippedRuneIds.length} 枚晶元强化了初始属性。`);if(profile.finalThrone)log('最后的王座回应了你：本次远征全属性 +25%。');nextWave();if(localQaSafe)for(const enemy of enemies){enemy.speed=0;enemy.attack=0;enemy.skill=99999;}if(localQaSafe&&runtimeParams.has('freeze')&&enemies[0])applySlow(enemies[0],999);updateUI();}
function safeEnemyPoint(origin,r=12){const choices=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++){const pos=center(x,y),reachable=lineOfSight(map,p,pos)||findPath(map,p,pos).length>0;if(walkable(map,pos.x,pos.y,r)&&reachable&&distance(p,pos)>70&&enemies.every(e=>e.hp<=0||distance(e,pos)>e.r+r+8))choices.push({pos,d:distance(origin,pos)});}choices.sort((a,b)=>a.d-b.d);return choices[0]?.pos||center(12,14);}
function enemyPositionReachable(enemy){if(!walkable(map,enemy.x,enemy.y,enemy.r))return false;if(lineOfSight(map,p,enemy))return true;if(enemy.reachMap===map&&enemy.reachX===Math.floor(enemy.x/TILE)&&enemy.reachY===Math.floor(enemy.y/TILE))return enemy.reachValid;enemy.reachMap=map;enemy.reachX=Math.floor(enemy.x/TILE);enemy.reachY=Math.floor(enemy.y/TILE);enemy.reachValid=findPath(map,p,enemy,p.r).length>0;return enemy.reachValid;}
function relocateEnemy(enemy,preferLast=false){const last={x:enemy.lastSafeX,y:enemy.lastSafeY};if(preferLast&&Number.isFinite(last.x)&&Number.isFinite(last.y)&&walkable(map,last.x,last.y,enemy.r)&&(lineOfSight(map,p,last)||findPath(map,p,last).length)){Object.assign(enemy,last);}else Object.assign(enemy,safeEnemyPoint(enemy,enemy.r));enemy.path=[];enemy.pathTimer=0;enemy.lastSafeX=enemy.x;enemy.lastSafeY=enemy.y;}
function bodyHasClearRoute(body,goal){const length=distance(body,goal),steps=Math.max(1,Math.ceil(length/8));for(let i=1;i<=steps;i++)if(!walkable(map,body.x+(goal.x-body.x)*i/steps,body.y+(goal.y-body.y)*i/steps,body.r))return false;return true;}
function enemyApproachPath(enemy){
  const direct=findPath(map,enemy,p,enemy.r);if(direct.length)return direct;
  // The player's center may be legal for a small player but illegal for a boss.
  const goals=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++){const point=center(x,y);if(distance(point,p)<160&&walkable(map,point.x,point.y,enemy.r)&&lineOfSight(map,point,p))goals.push(point);}
  goals.sort((a,b)=>distance(a,p)-distance(b,p));for(const point of goals.slice(0,12)){const route=findPath(map,enemy,point,enemy.r);if(route.length)return route;}return [];
}
function lateFloorMultiplier(depth=floor){return depth===4?2:depth===5?3:depth>=6?4:1;}
function spawnEnemy(type,pos,elite=false,summoned=false){const boss=type==='boss',profile=bossProfiles[floor-1]||bossProfiles.at(-1),scale=enemyScale(floor),mode=difficulties[difficulty],lateScale=lateFloorMultiplier(),damageMultiplier=boss?8:floor<=2?8:floor<=4?15:20;const config={crawler:{hp:28,r:12,speed:72,attack:9},brute:{hp:68,r:16,speed:43,attack:17},archer:{hp:35,r:12,speed:48,attack:11},wraith:{hp:42,r:12,speed:98,attack:10},splitter:{hp:57,r:14,speed:62,attack:13},shaman:{hp:49,r:14,speed:42,attack:10},assassin:{hp:39,r:11,speed:116,attack:16},summoner:{hp:64,r:15,speed:38,attack:8},boss:{hp:520,r:27,speed:36,attack:32}}[type]||{hp:28,r:12,speed:72,attack:9};if(!walkable(map,pos.x,pos.y,config.r))pos=safeEnemyPoint(pos,config.r);const health=Math.round(config.hp*scale.health*(elite?1.65:1)*mode.health*lateScale),lives=boss?profile.lives:1;enemies.push({id:++enemyId,...pos,type,r:config.r,hp:health,maxHp:health,lifeHp:health,lives,totalLives:lives,phase:1,form:boss?profile.forms[0]:'',speed:config.speed+floor*3,attack:Math.round((config.attack*scale.attack+floor*2)*damageMultiplier*mode.damage*lateScale),damageMultiplier,lateScale,cd:rand(.65,1.5),skill:boss?2.2:2.5,slow:0,hit:0,boss,elite,summoned,path:[],pathTimer:0,split:false});}
function spawnPoint(){const choices=[];for(let y=2;y<ROWS-2;y++)for(let x=2;x<COLS-2;x++){const pos=center(x,y);if(walkable(map,pos.x,pos.y,24)&&distance(p,pos)>260&&enemies.every(e=>distance(e,pos)>50))choices.push(pos);}return pick(choices)||center(12,2);}
function safeDropPoint(origin){const choices=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++){const pos=center(x,y);if(!walkable(map,pos.x,pos.y,8))continue;const route=findPath(map,p,pos);if(route.length||distance(p,pos)<20)choices.push({pos,d:distance(origin,pos)});}choices.sort((a,b)=>a.d-b.d);return choices[0]?.pos||center(12,14);}
function landingSparks(pos,color='#d5b879'){for(let i=0;i<9;i++){const a=rand(-Math.PI*.9,-Math.PI*.1),speed=rand(35,105),life=rand(.22,.48);effects.push({type:'particle',x:pos.x,y:pos.y-3,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,size:rand(1,3),color,life,max:life});}}
function dropLoot(item,origin){const pos=safeDropPoint(origin);const drop={id:++lootId,...pos,item,born:elapsed,visualSeed:Math.random()*10};drops.push(drop);landingSparks(pos,rarities[item.rarity].color);tone(420,.055,'triangle',.018);return drop;}
function dropRuneChip(origin,guaranteed=false,rng=Math.random){const pos=safeDropPoint(origin),chip=makeRuneChip(rng),drop={id:++lootId,...pos,rune:chip,born:elapsed,visualSeed:rng()*10};drops.push(drop);landingSparks(pos,runeGrades[chip.grade].color);if(guaranteed)log(`${runeGrades[chip.grade].name}符文晶元从首领残骸中显现。`);return drop;}
function makeFieldItem(elite=false){const roll=Math.random(),rarity=elite?(roll<.06?3:2):(roll<.01?3:roll<.15?2:roll<.58?1:0);return makeItem(floor,rarity);}
function normalWaveCount(mode=difficulty){return {easy:4,normal:5,hard:7,hell:9,inferno:11}[mode]||4;}
function bossWave(){return normalWaveCount()+1;}
function isBossWave(){return wave===bossWave();}
function bossRewardInfo(depth=floor){return depth<=3?{symbol:'◆',name:'史诗装备',desc:'紫色史诗战利品已经显现',color:'#c18cff'}:depth===4?{id:'life',key:'4',symbol:'♥',name:'赤月生命圣器',desc:'按 4 释放：一次性恢复全部生命',color:'#ef6f70'}:depth===5?{id:'aegis',key:'5',symbol:'◴',name:'停滞神徽',desc:'按 5 释放：一次性获得 5 秒无敌',color:'#7eddf2'}:{symbol:'♜',name:'王座碎片',desc:'可在主界面重铸最后的王座',color:'#f0c76e'};}
function grantBossReward(){const info=bossRewardInfo();dropRuneChip(center(12,5),true);if(floor<=3){dropLoot(makeItem(floor,3),center(12,5));log(`${bossNames[floor-1]}留下了一件紫色史诗装备。`);}else if(floor===4){p.artifacts.push({...info,used:false});ring(p.x,p.y,82,info.color,6);log('获得神器“赤月生命圣器”：按 4 主动释放，本局仅可使用一次。');}else if(floor===5){p.artifacts.push({...info,used:false});ring(p.x,p.y,82,info.color,6);log('获得神器“停滞神徽”：按 5 主动释放，本局仅可使用一次。');}else{profile.throneFragments++;saveProfile('王座碎片保存');log(`获得王座碎片，当前持有 ${profile.throneFragments} 枚。`);}return info;}
function useArtifact(id){if(!canAct())return false;if(cleared){toast('神器只能在战斗中释放。');return false;}const artifact=(p.artifacts||[]).find(item=>item.id===id);if(!artifact){toast(id==='life'?'尚未获得赤月生命圣器。':'尚未获得停滞神徽。');return false;}if(artifact.used){toast(`${artifact.name}已经耗尽。`);return false;}if(id==='life'){if(p.hp>=p.maxHp){toast('生命已满，圣器没有被消耗。');return false;}p.hp=p.maxHp;artifact.used=true;ring(p.x,p.y,100,artifact.color,7);burst(p.x,p.y,artifact.color,36);flash('#d64e55',.09);log('赤月生命圣器释放：生命完全恢复，神器已经耗尽。');}else if(id==='aegis'){p.invuln=Math.max(p.invuln,5);artifact.used=true;ring(p.x,p.y,118,artifact.color,8);rune(p.x,p.y,88,artifact.color);flash('#8beaff',.07);log('停滞神徽释放：获得 5 秒绝对无敌，神器已经耗尽。');}else return false;tone(id==='life'?190:680,.3,id==='life'?'sawtooth':'sine',.045);updateUI();return true;}
function startBossDefeatCG(){const info=bossRewardInfo(),origin=lastBossDefeat||center(12,3);cinematic={time:0,duration:5.8,x:origin.x,y:origin.y,color:bossProfiles[floor-1]?.color||'#e7bc6c',boss:bossNames[floor-1],reward:info,depth:floor};screenShake=14;flash('#fff0c5',.3);tone(90,.65,'sawtooth',.055);}
function finishBossDefeatCG(){if(!cinematic)return;cinematic=null;settleWave(true);}
function updateBossDefeatCG(dt){if(!cinematic)return;cinematic.time+=dt;if(cinematic.time>=cinematic.duration)finishBossDefeatCG();}
function settleWave(bossBattle=false){p.gold+=20+floor*10;shopVisits++;refreshCount=0;generateStock();if(bossBattle){grantBossReward();p.potions++;}else if(Math.random()<.0035){dropRuneChip(center(12,5));log('清理房间后，你在瓦砾中发现了一枚稀有符文晶元。');}commitRunProgress();saveRunSnapshot('战斗结束存档');banner(bossBattle?'首领已陨落 · 战利品显现':'战场肃清 · 商人抵达');log(`战斗奖励 +${20+floor*10} 金币。荣誉与远征现场已自动保存。按 B 访问商店。`);if(bossBattle&&floor===6){for(const d of [...drops])collect(d);endRun(true);}updateUI();}
function nextWave(){cleared=false;wave++;roomKind=pick(roomPools[floor-1]||roomPools.at(-1));map=createMap(floor,roomKind);Object.assign(p,center(12,14));p.secondWindUsed=false;path=[];target=null;shots=[];hazards=[];eliteRound=eliteNext;eliteNext=false;const bossBattle=isBossWave();if(bossBattle){spawnEnemy('boss',center(12,3));for(let i=0;i<Math.min(7,floor+1);i++)spawnEnemy(i%3===0?'brute':i%2?'archer':'crawler',spawnPoint(),floor>=5&&i===0);banner(`${rooms[roomKind].name} · ${bossNames[floor-1]}`);}else{const pools=enemyPools[floor-1]||enemyPools.at(-1),count=6+floor*2+Math.min(wave,4);for(let i=0;i<count;i++){let type=pick(pools);if(floor>=2&&wave>=2&&i===0)type='splitter';if(floor>=3&&i===1)type='shaman';if(floor>=3&&wave>=2&&i===2)type='assassin';if(floor>=3&&wave%2===1&&i===0)type='summoner';const depthElite=floor>=4&&i<floor-3;spawnEnemy(type,spawnPoint(),eliteRound&&i<2||depthElite);}banner(`第 ${floor} 层 · ${rooms[roomKind].name} · ${eliteRound?'精英试炼':`普通战斗 ${wave} / ${normalWaveCount()}`}`);}log(bossBattle?`${bossNames[floor-1]}苏醒了，房间：${rooms[roomKind].name}。`:`${rooms[roomKind].name}：第 ${wave} 场普通战斗开始。`);}
function finishWave(){cleared=true;shots=[];hazards=[];target=null;path=[];if(isBossWave()){startBossDefeatCG();return;}settleWave(false);}
