function bossCast(e){if(isMirrorBoss(e)){mirrorCast(e);return;}const profile=bossProfiles[floor-1]||bossProfiles.at(-1),phase=e.phase||1,offset=Math.random()<.55?0:Math.floor(Math.random()*profile.moves.length),move=profile.moves[(phase-1+offset)%profile.moves.length];e.skill=Math.max(.9,4.45-floor*.3-phase*.14);castBossMove(e,move);if(floor>=4&&phase>=5&&Math.random()<.4){const second=profile.moves[(phase+2)%profile.moves.length];if(second!==move)castBossMove(e,second);}}
function hitPlayer(amount,source=null){if(p.invuln>0||p.hp<=0)return;const relic=p.equipment.relic||{},armor=playerStats(p).armor,mitigation=100/(100+armor*2),damage=Math.max(2,Math.round(amount*(p.buffs?.ward>0?.5:1)*mitigation*(1-(relic.damageReduction||0))));p.hp-=damage;p.invuln=.4;screenShake=3;textEffect(p.x,p.y-25,`−${damage}`,'#ff9d88');tone(95,.1,'sawtooth',.025);const thorns=(p.talents?.includes('thorns')?.25:0)+(relic.thorns||0);if(thorns&&source?.hp>0)harmEnemy(source,Math.max(1,Math.round(damage*thorns)));if(p.hp<=0&&p.talents?.includes('secondwind')&&!p.secondWindUsed){p.secondWindUsed=true;p.hp=Math.round(p.maxHp*.35);p.mana=Math.min(p.maxMana,p.mana+25);toast('绝境回响触发！');log('绝境回响救回了你，恢复生命与法力。');return;}if(p.hp<=0){p.hp=0;p.deathAnim=.9;deathSequence=.9;slowMotion=Math.max(slowMotion,.65);cameraZoom=Math.max(cameraZoom,.1);}}
