function resolvePlayerAttackTimeline(timeline){if(timeline.kind==='skill'){const {name,point,kind,unstable}=timeline.payload;resolvePlayerSkill(name,point,kind,unstable);return;}const {kind,facing}=timeline.payload,item=p.equipment.weapon,stats=playerStats(p),w=stats.weapon,live=enemies.filter(e=>e.hp>0);p.facing=facing;tone(kind==='staff'?320:180,.07,'triangle');weaponAttackEffect(item);if(kind==='sword'){const rarity=item.rarity||0;effects.push({type:'slash',x:p.x,y:p.y,angle:facing,life:.18,max:.18,r:78+rarity*4,color:weaponColor(item),rarity});if(rarity>=2)effects.push({type:'slash',x:p.x,y:p.y,angle:facing+.08,life:.23,max:.23,r:60+rarity*5,color:rarity>=4?'#fff4bd':weaponColor(item),rarity});for(const enemy of live){const angle=Math.atan2(enemy.y-p.y,enemy.x-p.x)-facing;if(distance(p,enemy)<=w.range+enemy.r&&Math.cos(angle)>.05&&lineOfSight(map,p,enemy)){const roll=damageRoll(1,enemy,true);harmEnemy(enemy,roll.amount,roll.crit);weaponImpact(enemy.x,enemy.y,item);}}}else{const nearest=timeline.payload.target?.hp>0?timeline.payload.target:null,roll=damageRoll(1,nearest,true);firePlayerShot(facing,roll.amount,item,kind==='staff');shots.at(-1).crit=roll.crit;}p.nextAttackBonus=0;}
