function endRun(won){if(runRewarded)return;runRewarded=true;finished=true;running=false;paused=true;p.hp=Math.max(0,p.hp);commitRunProgress('远征结算');clearRunSnapshot();const record={won,kills:p.kills,floor,time:Math.round(elapsed),difficulty};if(!best||(won&&!best.won)||(won===best.won&&p.kills>best.kills)){best=record;saveBest();}const baseReward=Math.max(1,(floor-1)*5+(wave-1)*2+Math.floor(p.kills/15)+(won?30:0)),diamonds=Math.max(1,Math.round(baseReward*difficulties[difficulty].reward*(1+(p.diamondBonus||0)))),battleCount=6*(normalWaveCount()+1);profile.diamonds+=diamonds;profile.totalRuns++;profile.totalWins+=won?1:0;profile.bestFloor=Math.max(profile.bestFloor,floor);if(won&&difficulty==='hard')profile.hardWins++;saveProfile('远征结算');updateUI();openModal('result',`<div class="modal-eyebrow">${won?'THE ABYSS REMEMBERS YOUR NAME':'EVERY DESCENT LEAVES A STORY'} · ${difficulties[difficulty].name}</div><h2 class="modal-title">${won?'带着传说归来':'本次远征已经结算'}</h2><p class="modal-subtitle">${won?`你击败了终焉化身，穿越六层深渊归来。<br>${battleCount} 场战斗与六位变形首领，都将记住你的名字。`:'你带着截至当前层数、场次和击杀数的战果返回营地。<br>本次远征已经结束，装备、金币和局内成长将随之重置。'}</p><div class="result-stats"><div><strong>${p.kills}</strong><span>击败敌人</span></div><div><strong>◆ ${diamonds}</strong><span>本局钻石</span></div><div><strong>${formatTime(elapsed)}</strong><span>远征用时</span></div></div><button class="primary wide" data-action="restart">返回主界面 →</button><p class="modal-note">钻石、荣誉与王座碎片已保存；装备、金币、神器和天赋将在新局重置。</p>`);}
function formatTime(t){return `${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;}
function pauseScreen(){if(!running||finished)return;if(modal.open){if(['pause','help','inventory','shop','confirm-settle'].includes(currentModal))closeModal();return;}openModal('pause','<div class="modal-eyebrow">TAKE A BREATH</div><h2 class="modal-title">营火仍在燃烧</h2><p class="modal-subtitle">你可以继续战斗、完整保存现场，或按当前进度结算本局奖励。</p><button class="primary wide" data-action="close">继续远征</button><div class="modal-actions"><button data-action="save-exit">保存并退出</button><button data-action="confirm-settle">结算并退出</button></div><div class="modal-actions"><button data-action="help">操作说明</button><button data-action="confirm-restart">重新开始</button></div><p class="modal-note">保存并退出不会结算钻石；下次可从同一场战斗继续。结算并退出会结束本局，并按当前层数、场次和击杀数发放奖励。</p>');}
