    e.moving=false;if(!e.attackTimeline&&(dist>stop||!los)){if(e.pathTimer<=0){e.path=enemyApproachPath(e);e.pathTimer=.45+Math.random()*.2;}let dest=los&&bodyHasClearRoute(e,p)?p:e.path[0];if(dest&&distance(e,dest)<8){e.path.shift();dest=e.path[0]||(bodyHasClearRoute(e,p)?p:null);}if(dest){const d=Math.max(1,distance(e,dest));e.facing=Math.atan2(dest.y-e.y,dest.x-e.x);e.moving=true;moveBody(map,e,(dest.x-e.x)/d*e.speed*(e.slow>0?.38:1)*dt,(dest.y-e.y)/d*e.speed*(e.slow>0?.38:1)*dt);}}
