    if(!mirror&&ranged&&dist<330&&los&&e.cd<=0&&!e.attackTimeline){const a=Math.atan2(p.y-e.y,p.x-e.x),color=e.type==='shaman'?'#7ed5a8':e.type==='summoner'?'#c092e4':'#e6a16d';e.facing=a;e.attackAnim=.48;e.attackTimeline=createAttackTimeline('enemy',{kind:'ranged',angle:a,color},.48,4,2);e.cd=Math.max(1.05,1.65-floor*.07);}
