function drawBossDefeatCG(){if(!cinematic)return;const c=cinematic,u=clamp(c.time/c.duration,0,1),burstProgress=clamp((u-.08)/.48,0,1),reveal=clamp((u-.5)/.24,0,1);ctx.save();ctx.fillStyle=`rgba(2,1,1,${.35+Math.sin(Math.min(1,u)*Math.PI)*.38})`;ctx.fillRect(0,0,1040,720);ctx.fillStyle='#020101';ctx.fillRect(0,0,1040,Math.round(62+u*18));ctx.fillRect(0,640-Math.round(u*18),1040,90);ctx.translate(c.x,c.y);ctx.strokeStyle=c.color;ctx.shadowColor=c.color;ctx.shadowBlur=28;ctx.lineWidth=6-3*u;ctx.beginPath();ctx.arc(0,0,34+burstProgress*180,0,Math.PI*2);ctx.stroke();for(let i=0;i<44;i++){const angle=i*2.399+c.depth*.41,distanceOut=18+burstProgress*(110+(i%9)*15),size=3+(i%5);ctx.save();ctx.rotate(angle+u*.7);ctx.fillStyle=i%4===0?'#fff0bd':c.color;ctx.globalAlpha=1-burstProgress*.68;ctx.fillRect(distanceOut,-size/2,size*2,size);ctx.restore();}ctx.rotate(u*1.8);ctx.strokeStyle='#f2d38a';ctx.lineWidth=2;for(let i=0;i<6;i++){ctx.rotate(Math.PI/3);ctx.beginPath();ctx.moveTo(48,0);ctx.lineTo(96+Math.sin(u*Math.PI)*38,0);ctx.stroke();}ctx.restore();ctx.save();ctx.textAlign='center';ctx.shadowColor='#000';ctx.shadowBlur=16;ctx.globalAlpha=clamp(u/.18,0,1)*(1-clamp((u-.48)/.16,0,1));ctx.fillStyle='#f4dfb0';ctx.font='600 23px "Microsoft YaHei"';ctx.fillText(`第 ${c.depth} 层首领`,520,236);ctx.font='600 46px "Microsoft YaHei"';ctx.fillText(c.boss,520,298);ctx.globalAlpha=reveal;ctx.fillStyle=c.reward.color;ctx.shadowColor=c.reward.color;ctx.shadowBlur=26;ctx.font='700 54px "Segoe UI Symbol","Microsoft YaHei"';ctx.fillText(c.reward.symbol,520,322);ctx.font='600 32px "Microsoft YaHei"';ctx.fillText(c.reward.name,520,382);ctx.fillStyle='#eadbbd';ctx.shadowColor='#000';ctx.shadowBlur=12;ctx.font='16px "Microsoft YaHei"';ctx.fillText(c.reward.desc,520,418);ctx.globalAlpha=clamp((u-.18)/.2,0,1);ctx.fillStyle='#a89472';ctx.font='12px "Microsoft YaHei"';ctx.fillText('空格键跳过',520,665);ctx.restore();}
