const elixirInfo={haste:{name:'疾行药剂',price:28,desc:'使用后 10 秒内移动速度 +35%',color:'#79d4c5'},fury:{name:'狂怒药剂',price:34,desc:'使用后 10 秒内造成伤害 +50%',color:'#e59a73'},ward:{name:'守护药剂',price:38,desc:'使用后 10 秒内受到伤害 −50%',color:'#9eb9ec'}};
function potionSummary(){const bag=p.elixirs||{haste:0,fury:0,ward:0},active=Object.entries(p.buffs||{}).filter(([,time])=>time>0).map(([kind,time])=>`${elixirInfo[kind].name} ${Math.ceil(time)}秒`);return `生命 ${p.potions} 瓶 · ${Object.values(bag).reduce((a,b)=>a+b,0)} 瓶药剂${active.length?` · ${active.join(' / ')}`:''}`;}
function renderPotionPanel(){if(currentModal!=='shop')return;const content=$('modal-content');if(!content?.querySelector)return;let panel=content.querySelector('#potion-panel');if(!panel){const anchor=content.querySelector('.shop-grid')||content.querySelector('.inventory-grid');if(!anchor)return;panel=document.createElement('div');panel.id='potion-panel';panel.className='potion-shop';anchor.after(panel);}const bag=p.elixirs||{haste:0,fury:0,ward:0};panel.innerHTML=`<div class="potion-shop-title"><span>特殊药剂</span><small>购买后用 Z / X / C 使用</small></div>${Object.entries(elixirInfo).map(([kind,info])=>`<div class="potion-row" style="--item:${info.color}"><div><strong>${info.name}</strong><small>${info.desc} · 持有 ${bag[kind]||0}</small></div><button data-elixir="${kind}" ${p.gold<info.price?'disabled':''}>${info.price} 金</button></div>`).join('')}`;}
function buyElixir(kind){const info=elixirInfo[kind];if(!info)return;if(p.gold<info.price){toast('金币不足。');return;}p.gold-=info.price;p.elixirs??={haste:0,fury:0,ward:0};p.elixirs[kind]++;log(`购入${info.name}。按 ${kind==='haste'?'Z':kind==='fury'?'X':'C'} 使用。`);tone(610,.09);renderPotionPanel();updateUI();}
function useElixir(kind){if(!canAct())return;p.elixirs??={haste:0,fury:0,ward:0};p.buffs??={haste:0,fury:0,ward:0};if(!p.elixirs[kind]){toast(`${elixirInfo[kind].name}用完了，可在战后商店购买。`);return;}if(p.buffs[kind]>0){toast(`${elixirInfo[kind].name}效果还在持续。`);return;}p.elixirs[kind]--;p.buffs[kind]=10;if(kind==='haste')p.bonusSpeed=(p.bonusSpeed||0)+.35;toast(`使用${elixirInfo[kind].name} · ${elixirInfo[kind].desc.split('使用后 ')[1]}`);tone(kind==='fury'?240:kind==='ward'?430:680,.14);setTimeout(()=>{if(p.buffs[kind]>0){p.buffs[kind]=0;if(kind==='haste')p.bonusSpeed=Math.max(0,(p.bonusSpeed||0)-.35);updateUI();}},10000);updateUI();}
if(typeof MutationObserver!=='undefined')new MutationObserver(()=>renderPotionPanel()).observe($('modal-content'),{childList:true});
if(typeof MutationObserver!=='undefined')$('modal-content').addEventListener('click',event=>{const button=event.target.closest?.('button');if(button?.dataset.elixir)buyElixir(button.dataset.elixir);});
window.addEventListener('keydown',event=>{if(modal.open)return;const key=event.key.toLowerCase();if(key==='3')switchWeapon();if(key==='4')useArtifact('life');if(key==='5')useArtifact('aegis');if(key==='z')useElixir('haste');if(key==='x')useElixir('fury');if(key==='c')useElixir('ward');});
$('switch-weapon').onclick=switchWeapon;$('artifact-life').onclick=()=>useArtifact('life');$('artifact-aegis').onclick=()=>useArtifact('aegis');
function renderPotionTray(){const tray=$('potion-tray');if(!tray)return;tray.dataset??={};const bag=p.elixirs||{},key=`${p.potions||0}|${bag.haste||0}|${bag.fury||0}|${bag.ward||0}`;if(tray.dataset.state===key)return;tray.dataset.state=key;const life=Array.from({length:Math.min(p.potions||0,9)},()=>'<i class="potion-slot filled" title="生命药水"></i>').join('');const special=[['Z','haste','#79d4c5'],['X','fury','#e59a73'],['C','ward','#9eb9ec']].map(([key,kind,color])=>Array.from({length:bag[kind]||0},()=>`<i class="elixir-slot filled" style="--item:${color}" title="${key} · ${kind}">${key}</i>`).join('')).join('');tray.innerHTML=life+special;tray.title=`生命药水 ${p.potions||0} 瓶 · 特殊药剂 ${Object.values(bag).reduce((a,b)=>a+b,0)} 瓶`;}
function updateSkillLabels(){for(const key of ['dash','spin','frost']){const info=skillInfoFor(key),cost=Math.ceil(info.cost*(p.talents?.includes('unstable')?1.2:1)*(p.runeManaCost||1)),cooldown=key==='dash'?4.2:key==='spin'?9:13,range=castRangeFor(key),casting=pendingCast===key||queuedCast?.name===key,state=p.cd[key]>0?`${p.cd[key].toFixed(1)} 秒`:`${cost} 法力 · ${casting?'施法指令中':'就绪'}`,button=$(key),detail=`${info.name}\n法力 ${cost} · 基础冷却 ${cooldown} 秒 · 最大距离 ${range}\n${skillDetails[p.equipment.weapon.kind]?.[key]||''}`; $(`${key}-cd`).textContent=state;button.classList.toggle('targeting',casting);button.dataset.tooltip=detail;button.setAttribute('aria-label',detail);const title=$(`${key}-name`);if(title)title.textContent=info.name;}}
const baseUpdateUI=updateUI;updateUI=()=>{baseUpdateUI();$('potions').textContent=potionSummary();renderPotionTray();updateSkillLabels();};
const balancedShowShopBase=showShop;showShop=(tab='buy')=>{balancedShowShopBase(tab);const content=$('modal-content');if(currentModal!=='shop'||!content?.querySelector)return;const heal=content.querySelector('[data-action="heal"]');if(heal){const cost=70+floor*25;heal.disabled=p.gold<cost||p.hp>=p.maxHp;heal.innerHTML=`营火治疗 · 恢复全部生命<span>${cost} 金</span>`;}const potionButton=content.querySelector('[data-action="buy-potion"]');if(potionButton){potionButton.disabled=p.gold<59||p.potions>=9;potionButton.innerHTML=`生命药水（恢复 50% 最大生命）<span>59 金 · 持有 ${p.potions}/9</span>`;}const vitality=content.querySelector('[data-action="vitality"]');if(vitality){vitality.disabled=p.gold<240;vitality.innerHTML='坚韧祝福 · 本局最大生命 +200<span>240 金 · 同时恢复 200</span>';}const leave=content.querySelector('[data-action="leave-shop"]');if(leave)leave.innerHTML=`${isBossWave()?'进入下一层':'继续战斗'} →`;};
const relicUpdateUIBase=updateUI;updateUI=()=>{relicUpdateUIBase();if(!p.relicSlot)return;const item=p.equipment.relic;$('equipment').innerHTML+=`<div class="equip-slot relic-slot" style="--item:${item?rarities[item.rarity].color:'#b989db'}"><span class="equip-icon">✥</span><div><strong>${item?item.name:'未装备遗物'}</strong><small>${item?itemStats(item):'第四圣约已开启 · 在局内商店寻找遗物'}</small></div></div>`;};
const artifactUpdateUIBase=updateUI;updateUI=()=>{artifactUpdateUIBase();if(running)$('objective').textContent=cinematic?'首领陨落 · 神器正在显现':cleared?'战场肃清 · B 商店 / 传送门继续':isBossWave()?`首领战 · 剩余 ${enemies.filter(e=>e.hp>0).length} 个敌人`:`普通战斗 ${wave}/${normalWaveCount()} · 剩余 ${enemies.filter(e=>e.hp>0).length} 个敌人`;for(const artifact of p.artifacts||[])$('equipment').innerHTML+=`<div class="equip-slot artifact-slot ${artifact.used?'artifact-spent':''}" style="--item:${artifact.color}"><span class="equip-icon">${artifact.symbol}</span><div><strong>${artifact.name}</strong><small>${artifact.used?'已经耗尽':artifact.desc}</small></div></div>`;for(const [id,artifactId] of [['artifact-life','life'],['artifact-aegis','aegis']]){const button=$(id),artifact=(p.artifacts||[]).find(item=>item.id===artifactId);button.disabled=!running||!artifact||artifact.used||cleared||!!cinematic;button.classList.toggle('artifact-ready',!!artifact&&!artifact.used&&!cleared&&!cinematic);button.classList.toggle('artifact-spent',!!artifact?.used);button.querySelector?.('small')?.replaceChildren(artifact?(artifact.used?'已耗尽':'单次 · 就绪'):'尚未获得');}};
const relicSkillBase=skill;skill=(name,castPoint=null,confirmed=false)=>{const before=p.cd[name]||0,manaBefore=p.mana,kind=p.equipment.weapon.kind;relicSkillBase(name,castPoint,confirmed);const rate=(p.equipment.relic?.cooldownRate||1)*(p.runeCooldown||1);if(rate<1&&p.cd[name]>before)p.cd[name]*=rate;if(confirmed&&p.mana<manaBefore&&!(kind==='staff'&&name==='dash')){p.attackAnim=.44;cameraZoom=Math.max(cameraZoom,.025);effects.push({type:'ghost',x:p.x-Math.cos(p.facing)*14,y:p.y-Math.sin(p.facing)*14,facing:p.facing,kind,row:2,life:.24,max:.24});}};
