const v7HitPlayerBase=hitPlayer;hitPlayer=(amount,source=null)=>{const before=p.hp;v7HitPlayerBase(amount,source);if(p.hp<before){const loss=before-p.hp;p.hit=.24;if(loss>p.maxHp*.22)p.knockdown=.3;hitStop=Math.max(hitStop,.035);cameraZoom=Math.max(cameraZoom,.035);effects.push({type:'ghost',x:p.x-Math.cos(p.facing)*8,y:p.y-Math.sin(p.facing)*8,facing:p.facing,kind:p.equipment.weapon.kind,row:3,life:.18,max:.18});}};
const v7HarmEnemyBase=harmEnemy;harmEnemy=(enemy,amount,critical=false)=>{const wasAlive=enemy.hp>0,near=distance(p,enemy)<110;v7HarmEnemyBase(enemy,amount,critical);if(!wasAlive)return;enemy.hit=Math.max(enemy.hit||0,.18);hitStop=Math.max(hitStop,critical?.055:.022);if(enemy.hp<=0&&!enemy.boss){corpses.push({...enemy,life:.85,maxLife:.85,deathRotate:Math.cos(enemy.facing||0)>=0?.9:-.9});corpses=corpses.slice(-18);if(near&&p.equipment.weapon.kind==='sword'&&elapsed-(p.lastExecutionTime??-10)>1.6){p.lastExecutionTime=elapsed;p.executionAnim=.48;slowMotion=Math.max(slowMotion,.5);hitStop=Math.max(hitStop,.09);cameraZoom=Math.max(cameraZoom,.08);effects.push({type:'ghost',x:p.x,y:p.y,facing:p.facing,kind:'sword',row:5,life:.35,max:.35});}}};
const relicPotionBase=potion;potion=()=>{const before=p.potions;relicPotionBase();if(p.potions<before&&p.equipment.relic?.healBonus){p.hp=Math.min(p.maxHp,p.hp+p.maxHp*p.equipment.relic.healBonus);textEffect(p.x,p.y-42,'遗物强化治疗','#e3b4ef');updateUI();}};$('potion').onclick=potion;
