if(typeof setInterval!=='undefined')setInterval(()=>{if(!canAct())return;for(const e of enemies){if(e.hp<=0)continue;e.special=(e.special||0)-.25;if(e.type==='shaman'&&e.special<=0){e.special=4.5;const ally=enemies.filter(other=>other!==e&&other.hp>0&&!other.boss&&other.hp<other.maxHp*.9).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(ally){ally.hp=Math.min(ally.maxHp,ally.hp+ally.maxHp*.14);textEffect(ally.x,ally.y-25,'治疗','#87e2b8');ring(ally.x,ally.y,28,'#78d3a5');}}if(e.type==='summoner'&&e.special<=0&&enemies.filter(other=>other.hp>0).length<15){e.special=5.5;spawnEnemy('crawler',{x:e.x+rand(-30,30),y:e.y+rand(-30,30)},false,true);textEffect(e.x,e.y-25,'召唤','#cf9aeb');ring(e.x,e.y,35,'#b78dde');}if(e.type==='assassin'&&e.special<=0){const d=distance(e,p);if(d>80&&d<360&&lineOfSight(map,e,p)){e.special=3.5;const a=Math.atan2(p.y-e.y,p.x-e.x),steps=8;for(let i=0;i<steps;i++)moveBody(map,e,Math.cos(a)*18,Math.sin(a)*18);ring(e.x,e.y,27,'#de8b9b');}}}},250);
